#Requires -Version 5.1
<#
  ================================================================
   SETUP GUI — Windows 11 Toolbox
   Compile avec ps2exe (-noConsole) pour obtenir Setup-Toolbox.exe :
   un vrai installateur graphique 1-fichier pour les clients.
   ∞ Infinity Coder — Derouiche Oussama — GPL-3.0
  ================================================================
#>
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

$script:Base = 'https://raw.githubusercontent.com/derouicheoussama/windows-toolbox/main'
$script:AppName = 'Windows 11 Toolbox'

# ---- Assets embarques (base64 injectes a la preparation) ----
$script:LogoB64 = ''
$script:IcoB64  = ''

$sync = [hashtable]::Synchronized(@{})
$sync.Queue = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))

# ---------------- Interface ----------------
$form = New-Object Windows.Forms.Form
$form.Text = "Installation — $script:AppName"
$form.Size = New-Object Drawing.Size(560, 470)
$form.FormBorderStyle = 'FixedDialog'
$form.MaximizeBox = $false
$form.StartPosition = 'CenterScreen'
$form.BackColor = [Drawing.Color]::White
$form.TopMost = $true

$ms = New-Object System.IO.MemoryStream(, [Convert]::FromBase64String($script:LogoB64))
$logoImg = [System.Drawing.Image]::FromStream($ms)
$ms.Close()
$pic = New-Object Windows.Forms.PictureBox
$pic.Image = $logoImg
$pic.Size = New-Object Drawing.Size(104, 104)
$pic.SizeMode = 'Zoom'
$pic.Location = New-Object Drawing.Point(28, 26)
$form.Controls.Add($pic)

$title = New-Object Windows.Forms.Label
$title.Text = $script:AppName
$title.Font = New-Object Drawing.Font('Segoe UI', 16, [Drawing.FontStyle]::Bold)
$title.ForeColor = [Drawing.Color]::FromArgb(31, 42, 68)
$title.AutoSize = $true
$title.Location = New-Object Drawing.Point(148, 30)
$form.Controls.Add($title)

$sub = New-Object Windows.Forms.Label
$sub.Text = 'Diagnostics · SSD · Réparations — ∞ Infinity Coder'
$sub.ForeColor = [Drawing.Color]::Gray
$sub.AutoSize = $true
$sub.Location = New-Object Drawing.Point(151, 66)
$form.Controls.Add($sub)

$verLabel = New-Object Windows.Forms.Label
$verLabel.Text = 'Version : détection au lancement de l''installation'
$verLabel.ForeColor = [Drawing.Color]::FromArgb(37, 99, 235)
$verLabel.AutoSize = $true
$verLabel.Location = New-Object Drawing.Point(151, 92)
$form.Controls.Add($verLabel)

$btnInstall = New-Object Windows.Forms.Button
$btnInstall.Text = 'INSTALLER'
$btnInstall.Size = New-Object Drawing.Size(190, 46)
$btnInstall.Location = New-Object Drawing.Point(148, 128)
$btnInstall.FlatStyle = 'Flat'
$btnInstall.FlatAppearance.BorderSize = 0
$btnInstall.BackColor = [Drawing.Color]::FromArgb(37, 99, 235)
$btnInstall.ForeColor = [Drawing.Color]::White
$btnInstall.Font = New-Object Drawing.Font('Segoe UI', 11, [Drawing.FontStyle]::Bold)
$form.Controls.Add($btnInstall)

$btnLaunch = New-Object Windows.Forms.Button
$btnLaunch.Text = 'LANCER L''APPLICATION'
$btnLaunch.Size = New-Object Drawing.Size(190, 46)
$btnLaunch.Location = New-Object Drawing.Point(148, 128)
$btnLaunch.FlatStyle = 'Flat'
$btnLaunch.FlatAppearance.BorderSize = 0
$btnLaunch.BackColor = [Drawing.Color]::FromArgb(21, 128, 61)
$btnLaunch.ForeColor = [Drawing.Color]::White
$btnLaunch.Font = New-Object Drawing.Font('Segoe UI', 11, [Drawing.FontStyle]::Bold)
$btnLaunch.Visible = $false
$form.Controls.Add($btnLaunch)

$status = New-Object Windows.Forms.Label
$status.Text = 'Prêt à installer. La dernière version est téléchargée depuis GitHub et vérifiée (SHA256).'
$status.ForeColor = [Drawing.Color]::FromArgb(60, 60, 70)
$status.AutoSize = $false
$status.Size = New-Object Drawing.Size(500, 40)
$status.Location = New-Object Drawing.Point(28, 196)
$form.Controls.Add($status)

$progress = New-Object Windows.Forms.ProgressBar
$progress.Size = New-Object Drawing.Size(500, 24)
$progress.Location = New-Object Drawing.Point(28, 240)
$form.Controls.Add($progress)

$log = New-Object Windows.Forms.RichTextBox
$log.Size = New-Object Drawing.Size(500, 130)
$log.Location = New-Object Drawing.Point(28, 272)
$log.BackColor = [Drawing.Color]::FromArgb(30, 30, 40)
$log.ForeColor = [Drawing.Color]::FromArgb(220, 223, 228)
$log.Font = New-Object Drawing.Font('Consolas', 9)
$log.ReadOnly = $true
$form.Controls.Add($log)

$footer = New-Object Windows.Forms.Label
$footer.Text = 'GNU GPL-3.0 — Copyright (C) 2026 Derouiche Oussama · github.com/derouicheoussama/windows-toolbox'
$footer.ForeColor = [Drawing.Color]::Gray
$footer.AutoSize = $true
$footer.Location = New-Object Drawing.Point(28, 412)
$form.Controls.Add($footer)

$msIco = New-Object System.IO.MemoryStream(, [Convert]::FromBase64String($script:IcoB64))
$form.Icon = New-Object System.Drawing.Icon($msIco)
$msIco.Close()

function Add-SetupLog {
    param([string]$Text)
    $log.AppendText($Text + "`r`n")
    $log.SelectionStart = $log.TextLength
    $log.ScrollToCaret()
}

# ---------------- Moteur ----------------
$script:Job = $null
$script:Handle = $null
$script:InstalledPath = $null

$btnInstall.Add_Click({
    $btnInstall.Enabled = $false
    $status.ForeColor = [Drawing.Color]::FromArgb(37, 99, 235)
    $status.Text = 'Connexion à GitHub et installation en cours…'
    $ps = [powershell]::Create()
    $ps.Runspace.SessionStateProxy.SetVariable('q', $sync.Queue)
    $ps.Runspace.SessionStateProxy.SetVariable('base', $script:Base)
    $null = $ps.AddScript(@'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$installDir = Join-Path $env:LOCALAPPDATA 'Programs\WindowsToolbox'
$startMenu = Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs'
$desk = [Environment]::GetFolderPath('Desktop')
$psExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$icon = "$env:SystemRoot\System32\imageres.dll,-78"
$uninstKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\WindowsToolbox'

function Get-FileWithProgress([string]$url, [string]$dest) {
    $req = [System.Net.HttpWebRequest]::Create($url)
    $req.Timeout = 30000
    $req.ReadWriteTimeout = 60000
    $resp = $req.GetResponse()
    $total = $resp.ContentLength
    $rs = $resp.GetResponseStream()
    $fs = [System.IO.File]::Create($dest)
    $buf = New-Object byte[] 65536
    $read = 0; $last = -1
    while (($n = $rs.Read($buf, 0, $buf.Length)) -gt 0) {
        $fs.Write($buf, 0, $n); $read += $n
        if ($total -gt 0) {
            $pct = [int](100 * $read / $total)
            if ($pct -ne $last) { $last = $pct; $q.Enqueue("PCT|$pct") }
        }
    }
    $fs.Close(); $rs.Close(); $resp.Close()
}

try {
    $q.Enqueue('LOG|1/4 Lecture du manifeste de version…')
    $m = Invoke-RestMethod -Uri "$base/version.json" -TimeoutSec 25
    $q.Enqueue("VERSION|$($m.version)")
    $tmpDir = Join-Path $env:TEMP ('toolbox-setup-' + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Force -Path $tmpDir | Out-Null

    $q.Enqueue('LOG|2/4 Téléchargement de Windows-Toolbox.ps1…')
    $ps1Tmp = Join-Path $tmpDir 'Windows-Toolbox.ps1'
    Get-FileWithProgress "$base/Windows-Toolbox.ps1" $ps1Tmp
    if ($m.sha256) {
        $got = (Get-FileHash $ps1Tmp -Algorithm SHA256).Hash
        if ($got -ne $m.sha256) {
            $q.Enqueue('FAIL|Empreinte SHA256 différente du manifeste — installation refusée (sécurité).')
            Remove-Item $tmpDir -Recurse -Force -ErrorAction SilentlyContinue
            return
        }
        $q.Enqueue('LOG|Empreinte SHA256 vérifiée OK')
    }
    Invoke-WebRequest -Uri "$base/Uninstall-Toolbox.ps1" -OutFile (Join-Path $tmpDir 'Uninstall-Toolbox.ps1') -TimeoutSec 60 -UseBasicParsing
    Invoke-WebRequest -Uri "$base/Updater-Toolbox.ps1" -OutFile (Join-Path $tmpDir 'Updater-Toolbox.ps1') -TimeoutSec 60 -UseBasicParsing
    Invoke-WebRequest -Uri "$base/Lancer-Toolbox.cmd" -OutFile (Join-Path $tmpDir 'Lancer-Toolbox.cmd') -TimeoutSec 60 -UseBasicParsing

    $q.Enqueue('LOG|3/4 Installation des fichiers et raccourcis…')
    New-Item -ItemType Directory -Force -Path $installDir | Out-Null
    Copy-Item "$tmpDir\*" $installDir -Force
    New-Item -ItemType Directory -Force -Path (Join-Path $installDir 'tools') | Out-Null
    Set-Content -LiteralPath (Join-Path $installDir 'tools\LISEZMOI.txt') -Value "Place ici tes outils portables (.exe)." -Encoding UTF8

    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut((Join-Path $startMenu 'Windows 11 Toolbox.lnk'))
    $sc.TargetPath = $psExe
    $sc.Arguments = "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$installDir\Windows-Toolbox.ps1`""
    $sc.IconLocation = $icon
    $sc.WorkingDirectory = $installDir
    $sc.Save()
    $sc = $ws.CreateShortcut((Join-Path $desk 'Windows 11 Toolbox.lnk'))
    $sc.TargetPath = $psExe
    $sc.Arguments = "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$installDir\Windows-Toolbox.ps1`""
    $sc.IconLocation = $icon
    $sc.WorkingDirectory = $installDir
    $sc.Save()
    $sc = $ws.CreateShortcut((Join-Path $startMenu 'Windows 11 Toolbox - Desinstaller.lnk'))
    $sc.TargetPath = $psExe
    $sc.Arguments = "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$installDir\Uninstall-Toolbox.ps1`""
    $sc.IconLocation = $icon
    $sc.WorkingDirectory = $installDir
    $sc.Save()

    New-Item -Path $uninstKey -Force | Out-Null
    Set-ItemProperty $uninstKey 'DisplayName' 'Windows 11 Toolbox'
    Set-ItemProperty $uninstKey 'DisplayVersion' $m.version
    Set-ItemProperty $uninstKey 'Publisher' 'Derouiche Oussama - Infinity Coder'
    Set-ItemProperty $uninstKey 'DisplayIcon' $icon
    Set-ItemProperty $uninstKey 'InstallLocation' $installDir
    Set-ItemProperty $uninstKey 'UninstallString' "powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$installDir\Uninstall-Toolbox.ps1`""
    Set-ItemProperty $uninstKey 'NoModify' 1 -Type DWord
    Set-ItemProperty $uninstKey 'NoRepair' 1 -Type DWord

    Remove-Item $tmpDir -Recurse -Force -ErrorAction SilentlyContinue
    $q.Enqueue('LOG|4/4 Terminé.')
    $q.Enqueue("DONE|$($m.version)|$installDir")
} catch {
    $q.Enqueue('FAIL|' + $_.Exception.Message)
}
'@)
    $script:Job = $ps
    $script:Handle = $ps.BeginInvoke()
})

$btnLaunch.Add_Click({
    if ($script:InstalledPath) {
        Start-Process -FilePath 'powershell.exe' -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', "`"$script:InstalledPath`"")
        $form.Close()
    }
})

$form.Add_FormClosed({
    try { if ($script:Job) { $script:Job.Dispose() } } catch { }
})

$timer = New-Object Windows.Forms.Timer
$timer.Interval = 250
$timer.Add_Tick({
    try {
        while ($sync.Queue.Count -gt 0) {
            $line = [string]$sync.Queue.Dequeue()
            if ($line -like 'PCT|*') {
                $progress.Value = [Math]::Min(100, [int]($line.Substring(4)))
            }
            elseif ($line -like 'VERSION|*') {
                $verLabel.Text = 'Version installée : ' + $line.Substring(8)
            }
            elseif ($line -like 'LOG|*') {
                Add-SetupLog ($line.Substring(4))
            }
            elseif ($line -like 'DONE|*') {
                $p = $line -split '\|', 3
                $progress.Value = 100
                $script:InstalledPath = Join-Path $p[2] 'Windows-Toolbox.ps1'
                $status.ForeColor = [Drawing.Color]::FromArgb(21, 128, 61)
                $status.Text = "✓ $appName v$($p[1]) installé ! Raccourcis : Bureau + Menu Démarrer."
                $btnInstall.Visible = $false
                $btnLaunch.Location = New-Object Drawing.Point(148, 128)
                $btnLaunch.Visible = $true
                $form.Size = New-Object Drawing.Size(560, 500)
                $btnLaunch.Enabled = $true
            }
            elseif ($line -like 'FAIL|*') {
                $progress.Value = 0
                $status.ForeColor = [Drawing.Color]::FromArgb(185, 28, 28)
                $status.Text = '✗ ' + $line.Substring(5)
                $btnInstall.Enabled = $true
            }
            else { Add-SetupLog $line }
        }
    } catch { }
})
$timer.Start()

[void]$form.ShowDialog()
